"""Experimental bounded chord blend for ordinary corner-band guides.

Only internal guides move. Their endpoints, sampled curb positions and all
attributes are retained. The complete caller's cell, overlap, profile and
boundary guards remain responsible for acceptance. This is not a public recipe.
"""
import bpy
