def build(*, weight=.25):
    if not 0. < weight < 1.:
        raise ValueError('An internal blend strictly between zero and one is required')
    name=f'Prochitecture Streets / Ordinary guide chord blend v1 / {weight:g}'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name);g.socket('Samples','NodeSocketGeometry');g.socket('Eligible','NodeSocketBool')
    g.socket('Samples','NodeSocketGeometry','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput');source=inp.outputs['Samples']
    n=c._count(g,source)-1.
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);t=index/g.math('MAXIMUM',n,1.)
    a=g.separate(c._sample(g,source,g.position(),0,'FLOAT_VECTOR'))
    b=g.separate(c._sample(g,source,g.position(),n,'FLOAT_VECTOR'))
    p=g.separate(g.position());target=g.xyz(*[(1-weight)*x+weight*((1-t)*aa+t*bb) for x,aa,bb in zip(p,a,b)])
    # Collapsed guides are physical separator boundaries, not movable internal
    # curves. Reuse the caller's full-band eligibility and leave tapers alone.
    interior=g.math('GREATER_THAN',index,.5)*g.math('LESS_THAN',index,n-.5)*c.V(g,inp.outputs['Eligible'])
    result=g.setpos(source,c.choose(g,interior,target,g.position(),'VECTOR'))
    g.bind(result,out.inputs['Samples'])
    return g.g


def build_adaptive(*, weight=.25, minimum_weight=0.):
    """Correct a reversed mouth turn after preparation, retaining all grading.

    A convex center cell cannot span two guide edges with a negative signed
    turn. This is an applicability test, not acceptance: the complete caller
    still checks every cell and the whole surface. With no reversed mouth
    turn, the existing sample geometry passes through exactly.
    """
    if not 0. < weight < 1.:raise ValueError('Bounded internal blend required')
    if not 0. <= minimum_weight <= weight:raise ValueError('Minimum blend outside the bounded interval')
    name=f'Prochitecture Streets / Reversed-mouth guide correction v1 / {weight:g}'
    if minimum_weight:name+=f' / Guarded minimum {minimum_weight:g}'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for key in ('Samples','Mouths'):g.socket(key,'NodeSocketGeometry')
    g.socket('Rows','NodeSocketInt')
    g.socket('Samples','NodeSocketGeometry','OUTPUT');g.socket('Applied','NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    source=inp.outputs['Samples'];mouths=inp.outputs['Mouths'];n=c.V(g,inp.outputs['Rows']);pitch=n+1.
    sides=c._count(g,mouths);index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    point=lambda at:c._vec(g,c._sample(g,source,g.position(),at,'FLOAT_VECTOR'))
    previous=g.math('MODULO',index+sides-1.,sides)
    origin=point(index*pitch)
    a=c._sub(point(index*pitch+1.),origin);b=c._sub(point(previous*pitch+n-1.),origin)
    turn=c._cross(a,b)
    following=g.math('MODULO',index+1.,sides)
    inverse_rows=g.math('DIVIDE',1.,g.math('MAXIMUM',n,1.))
    chord_a=c._scale(c._sub(point(following*pitch),origin),inverse_rows)
    chord_b=c._scale(c._sub(point(previous*pitch),origin),inverse_rows)
    target_turn=c._cross(chord_a,chord_b)
    # A bounded heuristic estimate, twice the linearized correction. It tends
    # continuously to zero as the reversed turn disappears, rather than
    # switching abruptly to the maximum blend. Existing final guards certify
    # the result; this estimate is not a substitute for those checks.
    proposed=2.*g.math('MAXIMUM',-turn,0.)/g.math('MAXIMUM',g.math('ABSOLUTE',target_turn-turn),1e-12)
    probes=c._store(g,c._line(g,sides),'_og_weight',proposed)
    amount=g.math('MINIMUM',weight,c._stat(g,probes,c.named(g,'_og_weight'),'Max'))
    if minimum_weight:amount=g.math('MAXIMUM',minimum_weight,amount)
    need=g.math('GREATER_THAN',amount,0.)
    owner=g.math('FLOOR',index/pitch);row=g.math('MODULO',index,pitch);t=row/g.math('MAXIMUM',n,1.)
    nxt=g.math('MODULO',owner+1.,sides)
    eq=lambda a,b:g.math('COMPARE',a,b)
    eligible=(1.-eq(c._read(g,mouths,'st_cj_half',owner,'INT'),-1.))
    eligible*=1.-eq(c._read(g,mouths,'st_cj_half',nxt,'INT'),1.)
    eligible*=g.math('GREATER_THAN',row,.5)*g.math('LESS_THAN',row,n-.5)
    first=point(owner*pitch);last=point(owner*pitch+n);position=c._vec(g,g.position())
    target=g.xyz(*[(1.-amount)*x+amount*((1-t)*aa+t*bb) for x,aa,bb in zip(position,first,last)])
    moved=g.setpos(source,c.choose(g,eligible,target,g.position(),'VECTOR'))
    g.bind(c.choose(g,need,moved,source,'GEOMETRY'),out.inputs['Samples']);g.bind(need,out.inputs['Applied'])
    return g.g


def with_failed_cell_retry(original,candidate):
    """Preserve every accepted primitive; try a bounded guide layout otherwise."""
    g=c.Graph('Prochitecture Streets / Guarded corner-cell guide retry v1')
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET':
            g.socket(socket.name,socket.socket_type,socket.in_out,default=getattr(socket,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput');calls=[]
    for tree,label in ((original,'Original accepted corner layout'),(candidate,'Bounded retry after rejected corner cells')):
        node=g.node('GeometryNodeGroup',label);node.node_tree=tree
        for socket in node.inputs:g.bind(inp.outputs[socket.name],socket)
        calls.append(node)
    kinds={'NodeSocketGeometry':'GEOMETRY','NodeSocketBool':'BOOLEAN',
           'NodeSocketFloat':'FLOAT','NodeSocketInt':'INT','NodeSocketVector':'VECTOR'}
    # The Group Output also has a virtual socket used by the editor to add
    # outputs. Only declared interface sockets are part of this wrapper.
    for declared in original.interface.items_tree:
        if declared.item_type!='SOCKET' or declared.in_out!='OUTPUT':continue
        socket=out.inputs[declared.name]
        g.bind(c.choose(g,calls[0].outputs['Valid'],calls[0].outputs[socket.name],
                        calls[1].outputs[socket.name],kinds[socket.bl_idname]),socket)
    g.g['st_corner_guarded_retry']=1
    return g.g


